/**
 * The vendored engine and data are Agent_Loop_Sim's files at the pinned commit, byte for byte;
 * the vendored port reproduces the engine's own evals fixtures; and the site's fixtures were
 * generated by the Python reference at that same commit.
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import VENDORED from "@/lib/engine/vendor/VENDORED.json";

const ROOT = join(__dirname, "../..");
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
type Obj = Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

describe("vendored engine", () => {
  it("every file matches the SHA-256 recorded with its commit", () => {
    const files = Object.entries(VENDORED.files);
    expect(files.length).toBeGreaterThanOrEqual(40);
    expect(VENDORED.commit).toMatch(/^[0-9a-f]{40}$/);
    for (const [path, rec] of files)
      expect(sha(readFileSync(join(ROOT, path))), path).toBe(rec.sha256);
  });

  it("vendors the TS port with its evals module, its fixtures and recorded results", () => {
    const froms = Object.values(VENDORED.files).map((f) => f.from);
    for (const f of [
      "ts/src/evals/mathx.ts",
      "ts/src/evals/stats.ts",
      "ts/src/evals/generator.ts",
      "ts/src/evals/swe.ts",
      "ts/src/evals/study.ts",
      "ts/src/evals/index.ts",
      "ts/src/evals_data.json",
      "ts/src/rng.ts",
      "fixtures/evals_fixtures.json",
      "fixtures/evals_results.md",
      "ts/src/evals/judge.ts",
      "ts/src/evals/trajectory.ts",
      "ts/src/evals/scaffold.ts",
      "ts/src/evals/contamination.ts",
      "ts/src/evals2_data.json",
      "fixtures/evals2_fixtures.json",
      "fixtures/evals2_results.md",
      "traces/qwen-fix-test-react.json",
    ])
      expect(froms).toContain(f);
  });

  it("the engine's evals fixtures are reproduced by the vendored port", async () => {
    const { E } = await import("@/lib/engine");
    const fx = JSON.parse(
      readFileSync(join(ROOT, "tests/fixtures/evals_fixtures.json"), "utf8"),
    ) as Obj;
    expect(fx.engine).toBe("1.9.0");
    for (const [x, v] of fx.mathx.exp) expect(E.mathx.exp(x)).toBe(v);
    for (const [p, v] of fx.mathx.norm_ppf) expect(E.mathx.normPpf(p)).toBe(v);
    for (const [k, n, w, wi, ex] of fx.stats.intervals) {
      expect(E.stats.wald(k, n)).toEqual(w);
      expect(E.stats.wilson(k, n)).toEqual(wi);
      expect(E.stats.exact(k, n)).toEqual(ex);
    }
    expect(E.study.loopStudy()).toEqual(fx.loop);
    expect(E.study.passkStudy()).toEqual(fx.passk);
    expect(E.study.tieStudy()).toEqual(fx.tie);
    expect(E.study.pairedStudy(3)).toEqual(fx.paired["3"]);
    expect(E.study.uncertaintyStudy(50, "runs")).toEqual(
      fx.uncertainty["50|runs"],
    );
  });

  it("the engine's evals fixtures, part 2, are reproduced by the vendored port", async () => {
    const { E } = await import("@/lib/engine");
    const fx = JSON.parse(
      readFileSync(join(ROOT, "tests/fixtures/evals2_fixtures.json"), "utf8"),
    ) as Obj;
    expect(fx.engine).toBe("1.9.0");
    for (const [t, v] of fx.stats.kappa)
      expect(E.stats.cohenKappa(t)).toEqual(v);
    for (const [pts, v] of fx.stats.pareto)
      expect(E.stats.paretoFront(pts)).toEqual(v);
    expect(JSON.parse(JSON.stringify(E.judge.gradingStudy()))).toEqual(
      fx.grading,
    );
  });

  it("the site's fixtures come from the same commit", () => {
    const fx = JSON.parse(
      readFileSync(join(ROOT, "tests/fixtures/site_fixtures.json"), "utf8"),
    ) as { commit: string };
    expect(fx.commit).toBe(VENDORED.commit);
  });
});
